class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        abc = "abc"
        path = []
        ans = ""
        count = 0

        def backtrack():
            nonlocal count, ans
            if ans:
                return
            if len(path) == n:
                count += 1
                if count == k:
                    ans = ''.join(path[:])
                return

            for c in abc:
                if path and path[-1] == c:
                    continue

                path.append(c)
                backtrack()
                path.pop()

        backtrack()
        return ans
